    Bug 2012712 - Throw an error if S/MIME cert/key importing fails in tests. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D280594

diff --git a/mailnews/test/resources/SmimeUtils.sys.mjs b/mailnews/test/resources/SmimeUtils.sys.mjs
index 3c0724a9ad5..852f881717b 100644
--- a/mailnews/test/resources/SmimeUtils.sys.mjs
+++ b/mailnews/test/resources/SmimeUtils.sys.mjs
@@ -58,10 +58,13 @@ export const SmimeUtils = {
   },

   loadCertificateAndKey(file, pw) {
-    dump("Loading key from " + file.path + "\n");
+    dump("Loading key from " + file.path + " with password: [" + pw + "]\n");
     const certDB = Cc["@mozilla.org/security/x509certdb;1"].getService(
       Ci.nsIX509CertDB
     );
-    certDB.importPKCS12File(file, pw);
+    const importResult = certDB.importPKCS12File(file, pw);
+    if (importResult != 0) {
+      throw new Error("importPKCS12File failed, error code: " + importResult);
+    }
   },
 };
